// Runs before the request reaches Django: rejected requests cost the backend nothing.
const MAX_LENGTH = 100;
const RATE_LIMIT = 10;          // requests per client_id...
const WINDOW_MS = 60 * 1000;    // ...per minute
const ALLOWED_CHARS = /^[0-9a-zA-Z+\-*/%^().\s]+$/;
const ALLOWED_NAMES = new Set([
  'sin', 'cos', 'tan', 'asin', 'acos', 'atan', 'sqrt', 'log', 'ln', 'exp',
  'abs', 'floor', 'ceil', 'degrees', 'radians', 'factorial', 'pi', 'e',
]);

const body = $input.first().json.body ?? {};
const expression = body.expression;
const clientId = String(body.client_id || 'anonymous').slice(0, 100);
const reject = (status, error) => [{ json: { allowed: false, status, response: { expression: expression ?? null, error } } }];

// Sliding-window rate limit, state kept in workflow static data.
// Static data persists only between production executions, not manual test runs.
const store = $getWorkflowStaticData('global');
const now = Date.now();
store.hits ??= {};
for (const [id, times] of Object.entries(store.hits)) {
  const recent = times.filter((t) => now - t < WINDOW_MS);
  if (recent.length) store.hits[id] = recent;
  else delete store.hits[id];
}
const hits = store.hits[clientId] ?? [];
if (hits.length >= RATE_LIMIT) return reject(429, `too many requests: max ${RATE_LIMIT} per minute`);
store.hits[clientId] = [...hits, now];

if (typeof expression !== 'string' || !expression.trim()) return reject(400, 'expression must be a non-empty string');
if (expression.length > MAX_LENGTH) return reject(400, `expression is longer than ${MAX_LENGTH} characters`);
if (!ALLOWED_CHARS.test(expression)) return reject(400, 'expression contains forbidden characters');
// Names not preceded by a digit, so the "e" in 1e3 is not treated as a name.
const unknown = (expression.match(/(?<![0-9.])[a-zA-Z]+/g) ?? []).filter((name) => !ALLOWED_NAMES.has(name));
if (unknown.length) return reject(400, `unknown names: ${[...new Set(unknown)].join(', ')}`);

return [{ json: { allowed: true, expression, client_id: clientId } }];
